"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[40423],{3331:(e,s,i)=>{i.d(s,{R:()=>r,x:()=>o});var t=i(36672);const n={},a=t.createContext(n);function r(e){const s=t.useContext(a);return t.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function o(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),t.createElement(a.Provider,{value:s},e.children)}},88148:(e,s,i)=>{i.r(s),i.d(s,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>t,toc:()=>u});const t=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"D\xe9stresser Booking.com","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/fr/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17 avril 2023","top_news":"D\xe9stresser Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/fr/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/fr/2023/04/16"}}');var n=i(23420),a=i(3331);const r={localized_date:"17 avril 2023",top_news:"D\xe9stresser Booking.com"},o="2023-04-17",l={},u=[{value:"D\xe9stresser Booking.com",id:"d\xe9stresser-bookingcom",level:2},{value:"J&#39;ai utilis\xe9 Stable Diffusion et Dreambooth pour cr\xe9er un portrait artistique de mon chien.",id:"jai-utilis\xe9-stable-diffusion-et-dreambooth-pour-cr\xe9er-un-portrait-artistique-de-mon-chien",level:2},{value:"AT&amp;T Wireless Traffic Shaping rend apparemment certains sites web inutilisables",id:"att-wireless-traffic-shaping-rend-apparemment-certains-sites-web-inutilisables",level:2},{value:"Future Blues - Page Cowboy Bebop d&#39;Emily (1999)",id:"future-blues---page-cowboy-bebop-demily-1999",level:2},{value:"Lave-vaisselle Salmon",id:"lave-vaisselle-salmon",level:2},{value:"Pico3D : Moteur de jeu 3D \xe0 monde ouvert pour le PicoSystem (microcontr\xf4leur RP2040)",id:"pico3d--moteur-de-jeu-3d-\xe0-monde-ouvert-pour-le-picosystem-microcontr\xf4leur-rp2040",level:2},{value:"Wayback : Service d&#39;archivage auto-h\xe9berg\xe9 int\xe9gr\xe9 \xe0 Internet Archive",id:"wayback--service-darchivage-auto-h\xe9berg\xe9-int\xe9gr\xe9-\xe0-internet-archive",level:2},{value:"La biblioth\xe8que de composition math\xe9matique la plus rapide pour le web",id:"la-biblioth\xe8que-de-composition-math\xe9matique-la-plus-rapide-pour-le-web",level:2},{value:"&quot;Algebra for none&quot; \xe9choue \xe0 San Francisco",id:"algebra-for-none-\xe9choue-\xe0-san-francisco",level:2},{value:"La FSF d\xe9nonce l&#39;abandon par Google de JPEG-XL dans Chrome",id:"la-fsf-d\xe9nonce-labandon-par-google-de-jpeg-xl-dans-chrome",level:2}];function d(e){const s={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(s.header,{children:(0,n.jsx)(s.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,n.jsx)(s.h2,{id:"d\xe9stresser-bookingcom",children:"D\xe9stresser Booking.com"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Original"}),".\nL'auteur partage un article d'opinion sur l'utilisation excessive de tactiques de persuasion sur les sites de commerce \xe9lectronique, en particulier Booking.com, et pr\xe9sente son extension Chrome, \"De-stresser\", qui supprime les messages et notifications stressants de Booking.com, offrant ainsi aux utilisateurs une exp\xe9rience plus agr\xe9able. En cachant les balises de persuasion et en modifiant le langage pour qu'il soit plus positif, le De-stresser permet aux utilisateurs de r\xe9server plus calmement et de mani\xe8re plus d\xe9tendue. L'extension est d\xe9sormais disponible sur Booking.com."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),".\nBooking.com est critiqu\xe9 pour son utilisation de tactiques de vente \xe0 haute pression, y compris les messages d'urgence et les fen\xeatres pop-up qui peuvent dissuader les utilisateurs. Les d\xe9tracteurs affirment que cette approche privil\xe9gie les mesures \xe0 court terme au d\xe9triment de la fid\xe9lit\xe9 des clients \xe0 long terme. Les utilisateurs d\xe9clarent avoir trouv\xe9 des moyens de contourner ces tactiques, notamment en utilisant des extensions pour les bloquer ou les filtrer. Parall\xe8lement, les utilisateurs de Discussion Service d\xe9battent des m\xe9rites des tests A/B, certains soulignant qu'ils peuvent cr\xe9er des \"sch\xe9mas sombres\" sur les sites web. Malgr\xe9 ces pr\xe9occupations, de nombreux utilisateurs continuent d'utiliser des agr\xe9gateurs de r\xe9servation comme Booking.com et Expedia, soit pour des raisons de commodit\xe9, soit parce qu'ils offrent des prix et des politiques d'annulation avantageux. Certains experts soulignent que la r\xe9servation directe aupr\xe8s des h\xf4tels peut offrir de meilleures options de r\xe9solution des litiges, tandis que d'autres font remarquer que les taux de commission des sites de r\xe9servation peuvent varier consid\xe9rablement en fonction de l'h\xf4tel. N\xe9anmoins, les programmes de fid\xe9lisation des h\xf4tels peuvent offrir des avantages significatifs aux voyageurs fr\xe9quents."]}),"\n",(0,n.jsx)(s.h2,{id:"jai-utilis\xe9-stable-diffusion-et-dreambooth-pour-cr\xe9er-un-portrait-artistique-de-mon-chien",children:"J'ai utilis\xe9 Stable Diffusion et Dreambooth pour cr\xe9er un portrait artistique de mon chien."}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog"}),").\nCet article traite de l'utilisation des techniques d'IA Stable Diffusion et Dreambooth pour cr\xe9er un portrait peint de haute qualit\xe9 d'un chien. L'auteur partage l'ensemble de son flux de travail et fournit des instructions d\xe9taill\xe9es sur la mani\xe8re d'entra\xeener un mod\xe8le Dreambooth sur des photos de son chien. L'article traite \xe9galement de l'utilisation de l'upscaling pour agrandir de petites images en vue d'impressions de haute qualit\xe9 et pr\xe9sente la diffusion stable comme un changement de jeu pour le monde de l'art g\xe9n\xe9ratif texte-image."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nUn utilisateur de Discussion Service a utilis\xe9 Stable Diffusion et Dreambooth pour cr\xe9er un portrait artistique de son chien, tandis que les commentaires discutent de l'opposition \xe0 l'art de l'IA et des d\xe9bats autour du droit d'auteur et de l'utilisation \xe9quitable. L'utilisation de l'IA g\xe9n\xe9rative \xe0 des fins artistiques soul\xe8ve des questions \xe9thiques concernant le droit d'auteur et l'utilisation \xe9quitable, et les avis sont partag\xe9s \xe0 ce sujet. Certains ont critiqu\xe9 Stable Diffusion pour avoir utilis\xe9 des \u0153uvres d'art vol\xe9es sans compensation comme donn\xe9es d'entra\xeenement, tandis que d'autres ont fait l'\xe9loge de la technologie et de son potentiel d'innovation dans le domaine."]}),"\n",(0,n.jsx)(s.h2,{id:"att-wireless-traffic-shaping-rend-apparemment-certains-sites-web-inutilisables",children:"AT&T Wireless Traffic Shaping rend apparemment certains sites web inutilisables"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Original"}),".\nLe plan \" illimit\xe9 \" de 100 Mbits d'AT&T avec 50 Go de donn\xe9es prioritaires peut agressivement modeler le trafic, rendant certains sites web inutilisables, alors qu'un test a montr\xe9 qu'une carte SIM Verizon n'avait pas le m\xeame probl\xe8me. Le trafic d'Akamai montre des signes de manipulation intentionnelle du flux TCP. La mise en forme du trafic n'affecte que les comptes de donn\xe9es uniquement sur les comptes professionnels."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAT&T Wireless \xe9tranglerait les adresses IP de certains sites de streaming vid\xe9o, ce qui rendrait certains sites web inutilisables et provoquerait des divergences dans les tests de vitesse de l'internet. Les utilisateurs ont sugg\xe9r\xe9 des solutions telles que le d\xe9p\xf4t d'une plainte aupr\xe8s de la FCC, l'utilisation d'un VPN pour contourner l'\xe9tranglement, ou l'essai d'un APN diff\xe9rent. Certains commentateurs sont sceptiques quant \xe0 l'intention malveillante qui se cache derri\xe8re le bridage, tandis que d'autres proposent des solutions telles que des limites de d\xe9bit ou la d\xe9gradation de la qualit\xe9 vid\xe9o afin de pr\xe9server l'allocation de donn\xe9es."]}),"\n",(0,n.jsx)(s.h2,{id:"future-blues---page-cowboy-bebop-demily-1999",children:"Future Blues - Page Cowboy Bebop d'Emily (1999)"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://futureblues.com/",children:"Original"}),".\nD\xe9sol\xe9, il n'y a pas de texte fourni pour que je puisse le r\xe9sumer."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service expriment leur nostalgie pour les designs originaux et cr\xe9atifs des sites web classiques, qu'ils opposent \xe0 la nature standardis\xe9e, bruyante et mon\xe9tis\xe9e des sites web modernes, sugg\xe9rant un d\xe9sir pour des paysages m\xe9diatiques plus artistiques et centr\xe9s sur l'individualit\xe9. Des points de discussion \xe9mergent en comparant Wikip\xe9dia et Fandom, et la distinction entre les sites mobiles et les sites de bureau, et la conception du site Web inspire \xe0 la fois la nostalgie et l'\xe9tonnement pour sa long\xe9vit\xe9. Dans l'ensemble, l'article offre un aper\xe7u des bons souvenirs des utilisateurs des d\xe9buts de l'internet et fournit une plateforme pour discuter de l'\xe9tat actuel du web."]}),"\n",(0,n.jsx)(s.h2,{id:"lave-vaisselle-salmon",children:"Lave-vaisselle Salmon"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Original"}),".\nLe saumon au lave-vaisselle est un plat de poisson pr\xe9par\xe9 en enveloppant des morceaux de saumon dans au moins deux couches de papier d'aluminium et en les pla\xe7ant dans un lave-vaisselle pendant le cycle de lavage et de s\xe9chage. Cette m\xe9thode a \xe9t\xe9 d\xe9montr\xe9e pour la premi\xe8re fois aux \xc9tats-Unis par Vincent Price en 1975 et a depuis \xe9t\xe9 pr\xe9sent\xe9e dans divers m\xe9dias. Toutefois, la constance des temp\xe9ratures dans les lave-vaisselle suscite des inqui\xe9tudes, car elle peut entra\xeener une cuisson incompl\xe8te et des risques potentiels pour la sant\xe9."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nUn article de Hacker News sur la cuisson du saumon dans un lave-vaisselle suscite un d\xe9bat sur la s\xe9curit\xe9 de cette m\xe9thode de cuisson, les utilisateurs du secteur de la s\xe9curit\xe9 alimentaire s'opposant aux affirmations formul\xe9es dans l'enqu\xeate d'un YouTubeur. Bien que la s\xe9curit\xe9 de la cuisson au lave-vaisselle d\xe9pende de nombreux facteurs, une temp\xe9rature d'au moins 63\xb0C pendant 15 secondes est n\xe9cessaire pour tuer les bact\xe9ries du saumon."]}),"\n",(0,n.jsx)(s.h2,{id:"pico3d--moteur-de-jeu-3d-\xe0-monde-ouvert-pour-le-picosystem-microcontr\xf4leur-rp2040",children:"Pico3D : Moteur de jeu 3D \xe0 monde ouvert pour le PicoSystem (microcontr\xf4leur RP2040)"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Original"}),".\nLe moteur de jeu Pico3D utilise le deuxi\xe8me c\u0153ur du RP2040 comme rasterizer/GPU d\xe9di\xe9 pour faire tourner un jeu 3D \xe0 monde ouvert complet sur un microcontr\xf4leur \xe0 1 dollar. Le moteur contient une petite ville et ses environs avec des zombies sur lesquels il est possible de tirer, et des tutoriels Blender sont disponibles pour cr\xe9er des mondes de jeu. La simulation du moteur inclut actuellement 50 PNJ et 50 zombies en m\xeame temps, avec un rendu optimis\xe9 par la distance et l'\xe9limination des frustes vues."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nUn nouveau moteur de jeu 3D appel\xe9 Pico3D a \xe9t\xe9 d\xe9velopp\xe9 pour le microcontr\xf4leur RP2040 avec un \xe9cran de 120x120px. Il manque de m\xe9moire et de RAM vid\xe9o mais poss\xe8de une API unifi\xe9e. Les hackers sont enthousiastes \xe0 l'id\xe9e d'utiliser le Pico/RP2040 de mani\xe8re cr\xe9ative, et l'application unique de puces RAM dans le frame buffer fait ressortir cet article sur le site technologique."]}),"\n",(0,n.jsx)(s.h2,{id:"wayback--service-darchivage-auto-h\xe9berg\xe9-int\xe9gr\xe9-\xe0-internet-archive",children:"Wayback : Service d'archivage auto-h\xe9berg\xe9 int\xe9gr\xe9 \xe0 Internet Archive"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://github.com/wabarc/wayback",children:"Original"}),".\nWayback est un outil d'archivage auto-h\xe9berg\xe9 qui vise \xe0 capturer des pages web dans des capsules temporelles. Il est gratuit, open-source, multiplateforme et permet une int\xe9gration plus facile avec diverses plateformes, notamment Internet Archive, archive.today, IPFS et Telegraph. Il offre \xe9galement plusieurs options d'installation, notamment via GitHub, Snapcraft, APT, RPM et Homebrew."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),".\nLe service d'archivage auto-h\xe9berg\xe9 Wabarc capture des pages web dans des \"capsules temporelles\" et stocke des fichiers pour une utilisation hors ligne ; cependant, les utilisateurs de Discussion Service critiquent le manque de clart\xe9 du README et le manque de documentation. D'autres projets similaires incluent ArchiveBox, Shiori, DiskerNet et SingleFile ; HTTrack Website Copier est recommand\xe9 pour t\xe9l\xe9charger localement un site web entier, tandis que Browsertrix/Brozzler explore avec des navigateurs sans t\xeate pour la pr\xe9cision. Un utilisateur de Discussion Service recommande The Old Net pour naviguer dans des navigateurs anciens/modernes sans JS, et le repo li\xe9 a besoin de plus de clart\xe9 sur la partageabilit\xe9 et les normes d'archivage \xe9tablies."]}),"\n",(0,n.jsx)(s.h2,{id:"la-biblioth\xe8que-de-composition-math\xe9matique-la-plus-rapide-pour-le-web",children:"La biblioth\xe8que de composition math\xe9matique la plus rapide pour le web"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://katex.org/",children:"Original"}),".\nKaTeX est une biblioth\xe8que de composition math\xe9matique rapide pour le web qui offre une mise en page de qualit\xe9 d'impression bas\xe9e sur TeX de Donald Knuth, n'a pas de d\xe9pendances et peut facilement \xeatre int\xe9gr\xe9e aux ressources du site web pour un rendu c\xf4t\xe9 serveur \xe0 l'aide de Node.js. Son API simple rend efficacement les expressions math\xe9matiques, m\xeame sur des pages contenant de multiples expressions, sans limitation de navigateur ou d'environnement, et elle est open source sous la licence MIT."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, la biblioth\xe8que de composition math\xe9matique la plus rapide pour le web, ne prend pas en charge les diagrammes, ce qui la rend inadapt\xe9e pour certains math\xe9maticiens, tandis que MathJax et AsciiMath ont tous deux des projets similaires. Un site web de comparaison a \xe9t\xe9 partag\xe9, et les utilisateurs de Hacker News d\xe9battent des performances et de la praticit\xe9 de l'adaptation du balisage \xe0 diff\xe9rents contextes."]}),"\n",(0,n.jsx)(s.h2,{id:"algebra-for-none-\xe9choue-\xe0-san-francisco",children:'"Algebra for none" \xe9choue \xe0 San Francisco'}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco"}),").\nSelon une \xe9tude r\xe9alis\xe9e par des professeurs de Stanford, la politique \"Algebra for none\" du district scolaire de San Francisco Unified n'a pas permis d'am\xe9liorer les r\xe9sultats des \xe9l\xe8ves noirs et hispaniques en math\xe9matiques avanc\xe9es, ce qui a eu pour effet de creuser l'\xe9cart en mati\xe8re de r\xe9sultats. La d\xe9cision de retarder l'enseignement de l'alg\xe8bre jusqu'\xe0 la neuvi\xe8me ann\xe9e et de placer les \xe9l\xe8ves les moins performants et les plus performants dans les m\xeames classes n'a pas aid\xe9 les \xe9l\xe8ves les moins performants et a rendu plus difficile la r\xe9ussite des \xe9l\xe8ves les plus performants. Les familles qui en ont les moyens se sont tourn\xe9es vers les cours en ligne ou les \xe9coles priv\xe9es. Un groupe de parents a intent\xe9 une action en justice contre le district, affirmant qu'il violait la loi de l'\xc9tat sur l'acc\xe8s \xe9quitable aux math\xe9matiques avanc\xe9es."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nLa politique de San Francisco consistant \xe0 retarder l'alg\xe8bre jusqu'\xe0 la 9e ann\xe9e et \xe0 placer les \xe9l\xe8ves ayant des r\xe9sultats faibles, moyens et \xe9lev\xe9s dans les m\xeames classes a \xe9t\xe9 critiqu\xe9e, certains sugg\xe9rant que les concepts math\xe9matiques fondamentaux devraient \xeatre enseign\xe9s plus t\xf4t. Certains utilisateurs de Discussion Service sugg\xe8rent d'encourager la r\xe9ussite scolaire et extrascolaire en la liant \xe0 une r\xe9compense financi\xe8re, tandis que d'autres estiment que subventionner l'enseignement sup\xe9rieur par le biais de syst\xe8mes de cr\xe9dit permettant de payer l'universit\xe9 plus tard serait une meilleure solution. Des d\xe9bats ont lieu sur l'utilit\xe9 de l'enseignement traditionnel des math\xe9matiques et sur l'efficacit\xe9 d'une augmentation du financement pour r\xe9duire la taille des classes, certains utilisateurs sugg\xe9rant d'enseigner les math\xe9matiques par le biais de probl\xe8mes d'ing\xe9nierie et les avantages de l'enseignement en ligne."]}),"\n",(0,n.jsx)(s.h2,{id:"la-fsf-d\xe9nonce-labandon-par-google-de-jpeg-xl-dans-chrome",children:"La FSF d\xe9nonce l'abandon par Google de JPEG-XL dans Chrome"}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL"}),").\nLa Free Software Foundation critique la d\xe9cision de Google d'abandonner la prise en charge de JPEG-XL dans Chrome, soulignant la n\xe9cessit\xe9 d'un choix de navigateur et de formats de m\xe9dias libres. Malgr\xe9 le toll\xe9 de la communaut\xe9, les ing\xe9nieurs de Google ont continu\xe9 \xe0 prendre cette d\xe9cision, qui reste l'un des probl\xe8mes les plus \"\xe9toil\xe9s\" dans l'histoire du projet Chromium. Les utilisateurs ont montr\xe9 un fort soutien \xe0 JPEG-XL, mais l'accent mis par Google sur le contr\xf4le au d\xe9triment de la libert\xe9 semble pr\xe9valoir."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle est critiqu\xe9 par la Free Software Foundation pour avoir cess\xe9 de prendre en charge le format JPEG-XL dans Chrome, malgr\xe9 son adoption par les principaux \xe9diteurs d'images. Certains utilisateurs soutiennent que les formats plus anciens comme PNG et JPEG sont suffisants, tandis que d'autres pr\xe9f\xe8rent des codecs comme AVIF pour la vid\xe9o. Le d\xe9bat porte sur la viabilit\xe9 et l'adoption de nouveaux formats d'image dans l'\xe9cosyst\xe8me, avec le soutien et l'int\xe9r\xeat de l'industrie pour JPEG-XL, mais dont l'adoption d\xe9pend de la prise en charge par tous les principaux navigateurs."]})]})}function c(e={}){const{wrapper:s}={...(0,a.R)(),...e.components};return s?(0,n.jsx)(s,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);